seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()
n=len(seq)

# Tandem repeat finder (period up to 12, min total length ~ 2 copies min, report)
print("Tandem repeats (period<=20, >=2.5 copies or long):")
seen=set()
for p in range(1,21):
    i=0
    while i+p < n:
        # count repeats of unit seq[i:i+p]
        unit=seq[i:i+p]
        cnt=1
        j=i+p
        while seq[j:j+p]==unit:
            cnt+=1; j+=p
        if cnt>=2:
            span=j-i
            if cnt>=3 or (cnt>=2 and p>=6):
                key=(i,unit,cnt)
                if key not in seen:
                    seen.add(key)
                    print(f"  pos {i+1}-{j} len{span} unit={unit} x{cnt}")
            i=j
        else:
            i+=1

